#!/usr/bin/env python3
"""gen_recording.py: crates/iyakki-agent-api/src/facets_h/recording.rs, a `ServicesHandle` that notes the name of every call and passes it on (F-SPLIT-03,
UI-RPC-DESIGN.md section 6, the trace test). Same parser as the census; every method of the trait, defaults included, is delegated."""
import re, os, sys
sys.path.insert(0, os.path.dirname(__file__))
import rpc_census as c
ROOT = c.ROOT
def parse_trait():
    t = c.strip(open(ROOT + '/crates/iyakki-agent-api/src/facets_h.rs').read())
    i = t.index('pub trait ServicesHandle'); i = t.index('{', i) + 1
    d = 1; j = i
    while d:
        d += (t[j] == '{') - (t[j] == '}'); j += 1
    body = t[i:j - 1]; out = []; k = 0; depth = 0
    while k < len(body):
        ch = body[k]
        if ch == '{': depth += 1
        elif ch == '}': depth -= 1
        elif depth == 0 and body.startswith('fn ', k) and body[k - 1] in ' \n':
            m = re.match(r'fn (\w+)\s*\(', body[k:])
            a = k + m.end(); par = 1; e = a
            while par:
                par += (body[e] == '(') - (body[e] == ')'); e += 1
            args = ' '.join(body[a:e - 1].split())
            f = e; par = 0; ret = ''
            while f < len(body) and not (body[f] in ';{' and par == 0):
                par += (body[f] in '([') - (body[f] in ')]'); f += 1
            rest = body[e:f].strip()
            ret = ' '.join(rest[2:].split()) if rest.startswith('->') else ''
            out.append(dict(fn=m.group(1), args=args, ret=ret)); k = f; continue
        k += 1
    return out
ms = parse_trait()
def names(args):
    args = args.replace('->', '~~')
    out = []; d = 0; cur = ''
    for ch in args:
        if ch in '<([': d += 1
        if ch in '>)]': d -= 1
        if ch == ',' and d == 0: out.append(cur); cur = ''
        else: cur += ch
    if cur.strip(): out.append(cur)
    r = []
    for a in out:
        a = a.strip()
        if a in ('&self', '&mut self'): continue
        r.append(re.sub(r'^mut\s+', '', a.split(':')[0].strip()))
    return r
o = ['// GENERATED by dist/split/gen_recording.py. Do not edit: change the script or the trait and run it again.', '#![allow(clippy::all, unused_variables)]', 'use super::*;', '',
     '/// A `ServicesHandle` that records the name of every call it passes to the real one (the trace test of the first screens, UI-RPC-DESIGN.md section 6).', 'pub struct RecordingServices {', '    inner: Arc<dyn ServicesHandle>,', '    log: Mutex<Vec<String>>,', '}', '',
     'impl RecordingServices {', '    pub fn new(inner: Arc<dyn ServicesHandle>) -> RecordingServices {', '        RecordingServices { inner, log: Mutex::new(Vec::new()) }', '    }', '    fn note(&self, name: &str) {', '        self.log.lock().unwrap_or_else(std::sync::PoisonError::into_inner).push(name.to_string());', '    }',
     '    /// The names called so far, in order.', '    pub fn calls(&self) -> Vec<String> {', '        self.log.lock().unwrap_or_else(std::sync::PoisonError::into_inner).clone()', '    }', '    /// The distinct names called so far, sorted, with how often.', '    pub fn tally(&self) -> std::collections::BTreeMap<String, usize> {', '        let mut m = std::collections::BTreeMap::new();', '        for n in self.calls() { *m.entry(n).or_insert(0) += 1; }', '        m', '    }', '}', '',
     'impl ServicesHandle for RecordingServices {']
for r in ms:
    fn = r['fn']; args = r['args']; ret = r['ret']
    if fn == 'as_any':
        o.append('    fn as_any(&self) -> &dyn Any {\n        self.inner.as_any()\n    }'); continue
    if fn == 'as_any_arc':
        o.append('    fn as_any_arc(self: Arc<Self>) -> Arc<dyn Any + Send + Sync> {\n        self.inner.clone().as_any_arc()\n    }'); continue
    sig = f'    fn {fn}({args})' + (f' -> {ret}' if ret else '')
    o.append(sig + ' {')
    o.append(f'        self.note("{fn}");')
    o.append(f'        self.inner.{fn}({", ".join(names(args))})')
    o.append('    }')
o.append('}')
open(os.path.join(ROOT, 'crates/iyakki-agent-api/src/facets_h/recording.rs'), 'w').write('\n'.join(o) + '\n')
print('recording wrapper for', len(ms), 'methods')
